"use client";

import { useCallback, useId, useState } from "react";
import { createPortal } from "react-dom";

import { ArrowsShuffleIcon, DownloadIcon, TrashIcon } from "@/components/blocks/parts/icons";
import { Switch } from "@/components/motion/switch";
import { Button } from "@/components/ui/button";

import { computePivot, pivotToCsv } from "../lib/pivot-compute";
import {
  canPlace,
  DEFAULT_PIVOT,
  EMPTY_PIVOT,
  PIVOT_WELLS,
  type PivotConfig,
  placeField,
  removeField,
  swapAxes,
  wellFields,
} from "../lib/pivot-config";
import { BOOKING_RECORDS, isPivotMeasure, pivotDimension, pivotFieldLabel, type PivotFieldId, pivotMeasure } from "../lib/pivot-data";
import { BlockFrame } from "../parts/block-frame";
import { PivotChip } from "./pivot-builder/pivot-chip";
import { PivotChipMenu } from "./pivot-builder/pivot-chip-menu";
import { PivotFieldList } from "./pivot-builder/pivot-field-list";
import { PivotTable } from "./pivot-builder/pivot-table";
import { PivotWell } from "./pivot-builder/pivot-well";
import { type PivotDropTarget, usePivotDrag } from "./pivot-builder/use-pivot-drag";

const dropped = (config: PivotConfig, field: PivotFieldId, target: PivotDropTarget) =>
  target === "fields" ? removeField(config, field) : placeField(config, field, target);

const lowerList = (fields: PivotFieldId[]) => fields.map((field) => pivotFieldLabel(field).toLowerCase()).join(", then ");

/** The full account of the table for a screen reader: what it shows and what it adds up to. */
function describePivot(config: PivotConfig, totals: string[]): string {
  if (config.values.length === 0) return "No figure is in Values yet, so there are no numbers to show.";
  const figures = config.values.map(pivotFieldLabel).join(" and ");
  const rows = config.rows.length > 0 ? ` by ${lowerList(config.rows)}` : "";
  const columns = config.columns.length > 0 ? `, with a column for each ${lowerList(config.columns)}` : "";
  const hidden = config.filters.reduce((count, field) => count + config.excluded[field].length, 0);
  const filtered = hidden > 0 ? ` Filters leave out ${hidden} ${hidden === 1 ? "value" : "values"}.` : "";
  return `${figures}${rows}${columns}. Grand total: ${totals.join(" and ")}.${filtered}`;
}

/**
 * A pivot table builder over three months of bookings. Fields go into four
 * wells by drag or by menu, and the table below recomputes every cell,
 * subtotal and total from the records each time.
 */
export function PivotBuilder({ className }: { className?: string }) {
  const [config, setConfig] = useState<PivotConfig>(DEFAULT_PIVOT);
  const [shade, setShade] = useState(true);
  const titleId = useId();
  const shadeId = useId();

  const onDrop = useCallback((field: PivotFieldId, target: PivotDropTarget) => setConfig((current) => dropped(current, field, target)), []);
  const { drag, startDrag, ghostRef } = usePivotDrag(onDrop);

  // While a chip hovers over a place that takes it, the table shows the result before the drop.
  const preview = drag?.over ? dropped(config, drag.field, drag.over) : config;
  const previewing = preview !== config;
  const result = computePivot(BOOKING_RECORDS, preview);

  const totals = preview.values.map((measure) => {
    const index = result.columns.findIndex((column) => column.measure === measure && (column.total || preview.columns.length === 0));
    return `${pivotMeasure(measure).format(result.total[index] ?? 0)} ${measure === "revenue" ? "billed" : "bookings"}`;
  });

  const exportCsv = () => {
    const url = URL.createObjectURL(new Blob([pivotToCsv(result)], { type: "text/csv" }));
    const link = document.createElement("a");
    link.href = url;
    link.download = "fernhill-bookings-pivot.csv";
    link.click();
    URL.revokeObjectURL(url);
  };

  const chipNote = (field: PivotFieldId, filter: boolean) => {
    if (!filter || isPivotMeasure(field)) return undefined;
    const all = pivotDimension(field).values.length;
    return `${all - config.excluded[field].length} of ${all}`;
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-center justify-between gap-x-6 gap-y-3 border-b border-border px-5 py-4">
        <div className="min-w-0">
          <h2 id={titleId} className="text-base font-semibold">
            Bookings pivot
          </h2>
          <p className="truncate text-sm text-muted-foreground">August to October, five clinics</p>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <Button variant="outline" size="sm" onClick={() => setConfig(swapAxes)}>
            <ArrowsShuffleIcon aria-hidden="true" className="size-4" />
            Swap
            <span className="sr-only"> rows and columns</span>
          </Button>
          <Button variant="outline" size="sm" onClick={() => setConfig(EMPTY_PIVOT)}>
            <TrashIcon aria-hidden="true" className="size-4" />
            Clear
            <span className="sr-only"> the table</span>
          </Button>
          <Button variant="outline" size="sm" onClick={exportCsv} disabled={preview.values.length === 0}>
            <DownloadIcon aria-hidden="true" className="size-4" />
            Download
            <span className="sr-only"> data</span>
          </Button>
        </div>
      </header>

      <div className="grid border-b border-border @3xl:grid-cols-[16rem_1fr]">
        <div className="border-b border-border @3xl:border-r @3xl:border-b-0">
          <PivotFieldList
            config={config}
            onChange={setConfig}
            dragged={drag?.field ?? null}
            over={drag?.over === "fields"}
            onDragStart={startDrag}
          />
        </div>
        <div className="grid content-start gap-3 p-5 @2xl:grid-cols-2">
          {PIVOT_WELLS.map((well) => {
            const accepts = drag ? canPlace(drag.field, well.id) : false;
            const lands = drag?.over === well.id && accepts && !wellFields(config, well.id).includes(drag.field);
            return (
              <PivotWell
                key={well.id}
                target={well.id}
                label={well.label}
                empty={well.empty}
                dragState={drag ? (accepts ? "accepts" : "refuses") : "idle"}
                incoming={lands && drag ? pivotFieldLabel(drag.field) : null}
              >
                {wellFields(config, well.id).map((field) => (
                  <PivotChip
                    key={field}
                    label={pivotFieldLabel(field)}
                    note={chipNote(field, well.id === "filters")}
                    lifted={drag?.field === field}
                    onDragStart={(event) => startDrag(field, event)}
                  >
                    <PivotChipMenu field={field} config={config} onChange={setConfig} />
                  </PivotChip>
                ))}
              </PivotWell>
            );
          })}
        </div>
      </div>

      <div className="flex flex-col gap-3 p-5">
        <div className="flex flex-wrap items-center justify-between gap-x-6 gap-y-2">
          {/* One line that never wraps, so the table under it stays put while the figures change. */}
          <p className="h-5 min-w-0 flex-1 basis-64 truncate text-sm text-muted-foreground">
            {preview.values.length === 0 ? "Add a figure to see numbers." : `${previewing ? "Preview: " : ""}${totals.join(" and ")} in total.`}
          </p>
          <p aria-live="polite" className="sr-only">
            {previewing ? "Preview of the drop. " : ""}
            {describePivot(preview, totals)}
          </p>
          <label htmlFor={shadeId} className="flex cursor-pointer items-center gap-2 text-sm whitespace-nowrap text-muted-foreground">
            Shade cells
            <Switch id={shadeId} checked={shade} onCheckedChange={setShade} />
          </label>
        </div>
        {preview.values.length === 0 ? null : result.recordCount === 0 ? (
          <p className="text-sm">No bookings match the filters.</p>
        ) : (
          <PivotTable result={result} rowHeading={preview.rows.length > 0 ? preview.rows.map(pivotFieldLabel).join(", then ") : "Bookings"} shade={shade} />
        )}
      </div>

      {drag
        ? createPortal(
            <div ref={ghostRef} aria-hidden="true" className="pointer-events-none fixed top-0 left-0 z-50">
              <span className="inline-flex h-9 -translate-x-1/2 -translate-y-1/2 items-center rounded-lg whitespace-nowrap border border-border bg-background px-3 text-sm font-medium shadow-md">
                {pivotFieldLabel(drag.field)}
              </span>
            </div>,
            document.body,
          )
        : null}
    </BlockFrame>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

