import type { PivotConfig } from "./pivot-config";
import { type BookingRecord, pivotDimension, type PivotDimensionId, pivotMeasure, type PivotMeasureId } from "./pivot-data";

/** One number column of the pivot table. */
export interface PivotColumn {
  key: string;
  /** The value of each column field, outermost first. Empty for a total column. */
  path: string[];
  measure: PivotMeasureId;
  /** Set for the column that adds every column of one figure up. */
  total: boolean;
}

/** One cell of a header row, spanning one or more number columns. */
export interface PivotHeaderCell {
  key: string;
  label: string;
  span: number;
}

/** One row of the pivot table. A row with children is the subtotal of those children. */
export interface PivotRow {
  key: string;
  label: string;
  depth: number;
  hasChildren: boolean;
  /** The keys of the rows this row sits under, outermost first. */
  parents: string[];
  /** One number per column, in column order. */
  cells: number[];
}

/** A computed pivot table. */
export interface PivotResult {
  headerRows: PivotHeaderCell[][];
  columns: PivotColumn[];
  rows: PivotRow[];
  /** The grand total, one number per column. */
  total: number[];
  /** The largest innermost cell of each figure, for shading. */
  peaks: Record<PivotMeasureId, number>;
  /** How many records passed the filters. */
  recordCount: number;
}

const matches = (record: BookingRecord, fields: PivotDimensionId[], path: string[]) =>
  path.every((value, level) => {
    const field = fields[level];
    return field === undefined || record[field] === value;
  });

/** Every combination of the values of some fields, outermost field first. */
function combinations(fields: PivotDimensionId[]): string[][] {
  return fields.reduce<string[][]>(
    (paths, field) => paths.flatMap((path) => pivotDimension(field).values.map((value) => [...path, value])),
    [[]],
  );
}

function buildColumns(config: PivotConfig): PivotColumn[] {
  const paths = combinations(config.columns);
  const columns = paths.flatMap((path) =>
    config.values.map((measure): PivotColumn => ({ key: [...path, measure].join("/"), path, measure, total: false })),
  );
  if (config.columns.length === 0) return columns;
  const totals = config.values.map((measure): PivotColumn => ({ key: `total/${measure}`, path: [], measure, total: true }));
  return [...columns, ...totals];
}

function buildHeaderRows(config: PivotConfig, columns: PivotColumn[]): PivotHeaderCell[][] {
  const figures = config.values.length;
  const levels = config.columns.map((_, level) => {
    const cells: PivotHeaderCell[] = [];
    for (const column of columns) {
      const prefix = column.total ? "total" : column.path.slice(0, level + 1).join("/");
      const last = cells[cells.length - 1];
      if (last && last.key === prefix) last.span += 1;
      else cells.push({ key: prefix, label: column.total ? (level === 0 ? "Total" : "") : (column.path[level] ?? ""), span: 1 });
    }
    return cells;
  });
  const figureRow = columns.map((column): PivotHeaderCell => ({ key: column.key, label: pivotMeasure(column.measure).label, span: 1 }));
  return figures === 0 ? levels : [...levels, figureRow];
}

/**
 * Computes the pivot table for a set of wells: filters the records, lays the
 * column fields out across, nests the row fields down, and adds each figure
 * up for every cell, every subtotal row, the total column and the grand total.
 */
export function computePivot(source: BookingRecord[], config: PivotConfig): PivotResult {
  const records = source.filter((record) => config.filters.every((field) => !config.excluded[field].includes(record[field])));
  const columns = buildColumns(config);

  const cellsFor = (subset: BookingRecord[]) =>
    columns.map((column) =>
      subset.reduce((total, record) => (matches(record, config.columns, column.path) ? total + record[column.measure] : total), 0),
    );

  const rows: PivotRow[] = [];
  const peaks = { bookings: 0, revenue: 0 } satisfies Record<PivotMeasureId, number>;
  const lastDepth = config.rows.length - 1;

  const addRows = (subset: BookingRecord[], depth: number, parents: string[]) => {
    const field = config.rows[depth];
    if (field === undefined) return;
    for (const value of pivotDimension(field).values) {
      const group = subset.filter((record) => record[field] === value);
      if (group.length === 0) continue;
      const key = [...parents.slice(-1), value].join("/");
      const cells = cellsFor(group);
      rows.push({ key, label: value, depth, hasChildren: depth < lastDepth, parents, cells });
      if (depth === lastDepth) {
        columns.forEach((column, index) => {
          if (!column.total) peaks[column.measure] = Math.max(peaks[column.measure], cells[index] ?? 0);
        });
      }
      addRows(group, depth + 1, [...parents, key]);
    }
  };

  if (config.rows.length === 0 && records.length > 0) {
    rows.push({ key: "all", label: "All bookings", depth: 0, hasChildren: false, parents: [], cells: cellsFor(records) });
  } else {
    addRows(records, 0, []);
  }

  return { headerRows: buildHeaderRows(config, columns), columns, rows, total: cellsFor(records), peaks, recordCount: records.length };
}

const quote = (text: string) => (/[",\n]/.test(text) ? `"${text.replaceAll('"', '""')}"` : text);

/** The pivot table as CSV text, with one heading line that joins each column's path and figure. */
export function pivotToCsv(result: PivotResult): string {
  const heading = ["", ...result.columns.map((column) => [...(column.total ? ["Total"] : column.path), pivotMeasure(column.measure).label].join(" "))];
  const lines = result.rows.map((row) => [`${"  ".repeat(row.depth)}${row.label}`, ...row.cells.map(String)]);
  return [heading, ...lines, ["Grand total", ...result.total.map(String)]].map((line) => line.map(quote).join(",")).join("\n");
}

import { isPivotMeasure, type PivotDimensionId, type PivotFieldId, type PivotMeasureId } from "./pivot-data";

/** One of the four places a field can sit. */
export type PivotWellId = "filters" | "columns" | "rows" | "values";

/** The wells in the order the builder shows them. */
export const PIVOT_WELLS: { id: PivotWellId; label: string; empty: string }[] = [
  { id: "filters", label: "Filters", empty: "No filters. Every booking counts." },
  { id: "columns", label: "Columns", empty: "No columns. One column per figure." },
  { id: "rows", label: "Rows", empty: "No rows. One row for all bookings." },
  { id: "values", label: "Values", empty: "No figures. Add one to see numbers." },
];

/** Which fields sit in which well, and which values each filter leaves out. */
export interface PivotConfig {
  filters: PivotDimensionId[];
  columns: PivotDimensionId[];
  rows: PivotDimensionId[];
  values: PivotMeasureId[];
  /** The values a filter hides, by field. Only fields in the filters well apply. */
  excluded: Record<PivotDimensionId, string[]>;
}

const NOTHING_EXCLUDED = { clinic: [], visitType: [], channel: [], month: [] } satisfies PivotConfig["excluded"];

/** A pivot with every well empty. */
export const EMPTY_PIVOT: PivotConfig = { filters: [], columns: [], rows: [], values: [], excluded: NOTHING_EXCLUDED };

/** The pivot the builder opens with. */
export const DEFAULT_PIVOT: PivotConfig = {
  filters: ["channel"],
  columns: ["month"],
  rows: ["clinic", "visitType"],
  values: ["bookings"],
  excluded: NOTHING_EXCLUDED,
};

/** The fields in one well, in order. */
export function wellFields(config: PivotConfig, well: PivotWellId): PivotFieldId[] {
  return config[well];
}

/** The well a field sits in, or null when it is not placed. */
export function wellOf(config: PivotConfig, field: PivotFieldId): PivotWellId | null {
  return PIVOT_WELLS.find((well) => wellFields(config, well.id).includes(field))?.id ?? null;
}

/** Whether a well takes a field: figures go in values, grouping fields go anywhere else. */
export function canPlace(field: PivotFieldId, well: PivotWellId): boolean {
  return isPivotMeasure(field) === (well === "values");
}

/** The pivot without this field. A filter that leaves forgets its hidden values. */
export function removeField(config: PivotConfig, field: PivotFieldId): PivotConfig {
  if (isPivotMeasure(field)) return { ...config, values: config.values.filter((item) => item !== field) };
  return {
    ...config,
    filters: config.filters.filter((item) => item !== field),
    columns: config.columns.filter((item) => item !== field),
    rows: config.rows.filter((item) => item !== field),
    excluded: { ...config.excluded, [field]: [] },
  };
}

/** The pivot with this field at the end of a well. A field sits in one well at a time. */
export function placeField(config: PivotConfig, field: PivotFieldId, well: PivotWellId): PivotConfig {
  if (!canPlace(field, well) || wellOf(config, field) === well) return config;
  const cleared = removeField(config, field);
  if (isPivotMeasure(field)) return { ...cleared, values: [...cleared.values, field] };
  if (well === "filters") return { ...cleared, filters: [...cleared.filters, field] };
  if (well === "columns") return { ...cleared, columns: [...cleared.columns, field] };
  return { ...cleared, rows: [...cleared.rows, field] };
}

function shifted<T>(items: T[], item: T, step: -1 | 1): T[] {
  const from = items.indexOf(item);
  const to = from + step;
  if (from === -1 || to < 0 || to >= items.length) return items;
  const next = [...items];
  next.splice(from, 1);
  next.splice(to, 0, item);
  return next;
}

/** The pivot with this field one place earlier or later in its well. */
export function shiftField(config: PivotConfig, field: PivotFieldId, step: -1 | 1): PivotConfig {
  if (isPivotMeasure(field)) return { ...config, values: shifted(config.values, field, step) };
  return {
    ...config,
    filters: shifted(config.filters, field, step),
    columns: shifted(config.columns, field, step),
    rows: shifted(config.rows, field, step),
  };
}

/** The pivot with rows and columns swapped. */
export function swapAxes(config: PivotConfig): PivotConfig {
  return { ...config, rows: config.columns, columns: config.rows };
}

/** The pivot with one value of a filter hidden or shown again. */
export function toggleExcluded(config: PivotConfig, field: PivotDimensionId, value: string): PivotConfig {
  const hidden = config.excluded[field];
  const next = hidden.includes(value) ? hidden.filter((item) => item !== value) : [...hidden, value];
  return { ...config, excluded: { ...config.excluded, [field]: next } };
}

import { formatMoney, formatWhole } from "./format";
import { seededRandom } from "./plot";

/** A field a booking can be grouped by. */
export type PivotDimensionId = "clinic" | "visitType" | "channel" | "month";

/** A figure a booking carries. */
export type PivotMeasureId = "bookings" | "revenue";

/** Any field of the bookings data. */
export type PivotFieldId = PivotDimensionId | PivotMeasureId;

/** The bookings of one clinic, visit type, channel and month. */
export interface BookingRecord {
  clinic: string;
  visitType: string;
  channel: string;
  month: string;
  bookings: number;
  /** Dollars billed for those bookings. */
  revenue: number;
}

/** A grouping field with its values in display order. */
export interface PivotDimension {
  id: PivotDimensionId;
  label: string;
  values: string[];
}

/** A figure with its formatter. Every figure adds up. */
export interface PivotMeasure {
  id: PivotMeasureId;
  label: string;
  format: (value: number) => string;
}

// Each value carries a weight, so busy clinics and common visits get more bookings.
const CLINICS: [string, number][] = [
  ["Harbour Street", 1.3],
  ["Mill Lane", 1.1],
  ["Northgate", 0.95],
  ["Orchard Road", 0.8],
  ["The Quay", 0.6],
];
// The third number is the price of one visit in dollars.
const VISIT_TYPES: [string, number, number][] = [
  ["First visit", 0.7, 95],
  ["Follow-up", 1.2, 60],
  ["Treatment", 0.5, 140],
];
const CHANNELS: [string, number][] = [
  ["Booking page", 1.4],
  ["Phone", 0.8],
  ["Front desk", 0.5],
];
const MONTHS: [string, number][] = [
  ["Aug", 0.9],
  ["Sep", 1],
  ["Oct", 1.15],
];

const names = (rows: [string, ...number[]][]) => rows.map(([name]) => name);

/** The four grouping fields. */
export const PIVOT_DIMENSIONS: PivotDimension[] = [
  { id: "clinic", label: "Clinic", values: names(CLINICS) },
  { id: "visitType", label: "Visit type", values: names(VISIT_TYPES) },
  { id: "channel", label: "Channel", values: names(CHANNELS) },
  { id: "month", label: "Month", values: names(MONTHS) },
];

/** The two figures. */
export const PIVOT_MEASURES: PivotMeasure[] = [
  { id: "bookings", label: "Bookings", format: formatWhole },
  { id: "revenue", label: "Revenue", format: formatMoney },
];

/** Whether a field is a figure rather than a grouping field. */
export const isPivotMeasure = (field: PivotFieldId): field is PivotMeasureId => field === "bookings" || field === "revenue";

/** The label of any field. */
export function pivotFieldLabel(field: PivotFieldId): string {
  return [...PIVOT_DIMENSIONS, ...PIVOT_MEASURES].find((item) => item.id === field)?.label ?? field;
}

/** The grouping field with this id. */
export function pivotDimension(id: PivotDimensionId): PivotDimension {
  return PIVOT_DIMENSIONS.find((item) => item.id === id) ?? PIVOT_DIMENSIONS[0]!;
}

/** The figure with this id. */
export function pivotMeasure(id: PivotMeasureId): PivotMeasure {
  return PIVOT_MEASURES.find((item) => item.id === id) ?? PIVOT_MEASURES[0]!;
}

function buildRecords(): BookingRecord[] {
  const random = seededRandom(71);
  const records: BookingRecord[] = [];
  for (const [clinic, clinicWeight] of CLINICS) {
    for (const [visitType, typeWeight, price] of VISIT_TYPES) {
      for (const [channel, channelWeight] of CHANNELS) {
        for (const [month, monthWeight] of MONTHS) {
          const bookings = Math.max(1, Math.round(58 * clinicWeight * typeWeight * channelWeight * monthWeight * (0.85 + random() * 0.3)));
          records.push({ clinic, visitType, channel, month, bookings, revenue: bookings * price });
        }
      }
    }
  }
  return records;
}

/** Three months of bookings: one record per clinic, visit type, channel and month. */
export const BOOKING_RECORDS: BookingRecord[] = buildRecords();

const WHOLE = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });
const ONE_PLACE = new Intl.NumberFormat("en-US", { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const COMPACT = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 });
const MONEY = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 });

/** A whole number with thousands separators. */
export const formatWhole = (value: number) => WHOLE.format(Math.round(value));

/** A number with one decimal place. */
export const formatOnePlace = (value: number) => ONE_PLACE.format(value);

/** A short number for an axis, such as 1.2K. */
export const formatCompact = (value: number) => COMPACT.format(value);

/** A dollar amount with no cents. */
export const formatMoney = (value: number) => MONEY.format(Math.round(value));

/** A percent with one decimal place and no sign. */
export const formatPercent = (value: number) => `${ONE_PLACE.format(Math.abs(value))}%`;

const DAY = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", timeZone: "UTC" });
const WEEKDAY = new Intl.DateTimeFormat("en-US", { weekday: "long", timeZone: "UTC" });

/** The sample data ends on this day, so every block shows the same dates on every render. */
export const SAMPLE_END = Date.UTC(2026, 9, 31);

/** The date `daysBeforeEnd` days before the last sample day. */
export const sampleDate = (daysBeforeEnd: number) => new Date(SAMPLE_END - daysBeforeEnd * 86_400_000);

/** A short date, such as Oct 31. */
export const formatDay = (date: Date) => DAY.format(date);

/** A weekday name, such as Tuesday. */
export const formatWeekday = (date: Date) => WEEKDAY.format(date);

/**
 * Plot maths shared by the blocks. Every path is drawn in a 0 to 100 box, and
 * the SVG stretches it with `preserveAspectRatio="none"`, so a chart needs no
 * resize observer. Strokes keep their width through `vector-effect`.
 */

/** A repeatable random source, so sample data is the same on the server and in the browser. */
export function seededRandom(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state * 1664525 + 1013904223) >>> 0;
    return state / 4294967296;
  };
}

// Monday to Sunday: a working week that tails off, then a quiet weekend.
const WEEKDAY_LIFT = [0.35, 0.5, 0.2, 0.1, -0.05, -0.75, -1];

/** Sample data that moves from `start` to `end` with a working-week rhythm and some noise. */
export function makeSeries(seed: number, length: number, start: number, end: number, noise: number): number[] {
  const random = seededRandom(seed);
  return Array.from({ length }, (_, index) => {
    const progress = length === 1 ? 1 : index / (length - 1);
    const trend = start + (end - start) * progress;
    const week = (WEEKDAY_LIFT[index % 7] ?? 0) * noise * 0.6;
    return Math.max(0, trend + week + (random() - 0.5) * noise * 0.7);
  });
}

/** The lowest and highest value across several series, padded so a line never touches the frame. */
export function paddedExtent(series: number[][], padding = 0.12): [number, number] {
  const values = series.flat();
  const low = Math.min(...values);
  const high = Math.max(...values);
  const span = high - low || 1;
  return [Math.max(0, low - span * padding), high + span * padding];
}

/** Where a value sits in the box, from 0 at the top to 100 at the bottom. */
export function toY(value: number, [low, high]: [number, number]): number {
  return 100 - ((value - low) / (high - low || 1)) * 100;
}

/** Where a point sits across the box, from 0 to 100. */
export function toX(index: number, length: number): number {
  return length <= 1 ? 50 : (index / (length - 1)) * 100;
}

/** The value at a fractional position along a series, read off the straight line between its neighbours. */
function valueAt(values: number[], position: number): number {
  const left = Math.floor(position);
  const right = Math.min(values.length - 1, left + 1);
  const from = values[left] ?? 0;
  const to = values[right] ?? from;
  return from + (to - from) * (position - left);
}

/**
 * A line through `values` with a fixed number of segments. Two paths with the
 * same segment count can morph into each other, whatever their point counts.
 */
export function linePath(values: number[], extent: [number, number], samples = 60): string {
  if (values.length === 0) return "";
  const parts: string[] = [];
  for (let step = 0; step <= samples; step += 1) {
    const position = (step / samples) * (values.length - 1);
    const x = (step / samples) * 100;
    const y = toY(valueAt(values, position), extent);
    parts.push(`${step === 0 ? "M" : "L"}${x.toFixed(2)} ${y.toFixed(2)}`);
  }
  return parts.join(" ");
}

/** The same line, closed down to the bottom edge, for a filled area. */
export function areaPath(values: number[], extent: [number, number], samples = 60): string {
  const line = linePath(values, extent, samples);
  return line ? `${line} L100 100 L0 100 Z` : "";
}

/** Round axis values between the low and high of the plot. */
export function axisTicks([low, high]: [number, number], count = 4): number[] {
  return Array.from({ length: count }, (_, index) => low + ((high - low) * index) / (count - 1));
}

/** The percent change from `before` to `after`, or 0 when there is nothing to compare against. */
export function percentChange(before: number, after: number): number {
  return before === 0 ? 0 : ((after - before) / before) * 100;
}

/** The sum of a series. */
export function sum(values: number[]): number {
  return values.reduce((total, value) => total + value, 0);
}

/** The mean of a series. */
export function mean(values: number[]): number {
  return values.length === 0 ? 0 : sum(values) / values.length;
}

