/** Props for the menu of a field chip. */
export interface PivotChipMenuProps {
  field: PivotFieldId;
  config: PivotConfig;
  onChange: (config: PivotConfig) => void;
}

/**
 * The menu items of one field: add it to a well or move it to another, move
 * it earlier or later, pick the values a filter shows, and remove it.
 */
export function PivotChipMenu({ field, config, onChange }: PivotChipMenuProps) {
  const current = wellOf(config, field);
  const siblings = current ? wellFields(config, current) : [];
  const place = siblings.indexOf(field);
  const filterField = current === "filters" && !isPivotMeasure(field) ? field : null;

  return (
    <>
      {PIVOT_WELLS.filter((well) => well.id !== current && canPlace(field, well.id)).map((well) => (
        <DropdownMenuItem key={well.id} onSelect={() => onChange(placeField(config, field, well.id))}>
          {current ? "Move to" : "Add to"} {well.label.toLowerCase()}
        </DropdownMenuItem>
      ))}
      {current && siblings.length > 1 ? (
        <>
          <DropdownMenuSeparator />
          <DropdownMenuItem disabled={place === 0} onSelect={() => onChange(shiftField(config, field, -1))}>
            Move earlier
          </DropdownMenuItem>
          <DropdownMenuItem disabled={place === siblings.length - 1} onSelect={() => onChange(shiftField(config, field, 1))}>
            Move later
          </DropdownMenuItem>
        </>
      ) : null}
      {filterField ? (
        <>
          <DropdownMenuSeparator />
          <DropdownMenuLabel>Values to include</DropdownMenuLabel>
          {pivotDimension(filterField).values.map((value) => (
            <DropdownMenuCheckboxItem
              key={value}
              checked={!config.excluded[filterField].includes(value)}
              // Keep the menu open, so a person can tick several values in one visit.
              onSelect={(event) => event.preventDefault()}
              onCheckedChange={() => onChange(toggleExcluded(config, filterField, value))}
            >
              {value}
            </DropdownMenuCheckboxItem>
          ))}
        </>
      ) : null}
      {current ? (
        <>
          <DropdownMenuSeparator />
          <DropdownMenuItem onSelect={() => onChange(removeField(config, field))}>Remove</DropdownMenuItem>
        </>
      ) : null}
    </>
  );
}

