"use client";

import { type PointerEvent as ReactPointerEvent, useCallback, useEffect, useRef, useState } from "react";

import { PIVOT_WELLS, type PivotWellId } from "../../lib/pivot-config";
import type { PivotFieldId } from "../../lib/pivot-data";

/** Where a dragged field can land: a well, or the field list to take it out. */
export type PivotDropTarget = PivotWellId | "fields";

/** The field being dragged and the target under the pointer. */
export interface PivotDrag {
  field: PivotFieldId;
  over: PivotDropTarget | null;
}

/** The attribute a drop target carries, with its target id as the value. */
export const PIVOT_DROP_ATTRIBUTE = "data-pivot-drop";

// A press becomes a drag after the pointer travels this far, so a tap stays a tap.
const DRAG_THRESHOLD = 6;

function targetAt(x: number, y: number): PivotDropTarget | null {
  const name = document.elementFromPoint(x, y)?.closest(`[${PIVOT_DROP_ATTRIBUTE}]`)?.getAttribute(PIVOT_DROP_ATTRIBUTE);
  if (name === "fields") return "fields";
  return PIVOT_WELLS.find((well) => well.id === name)?.id ?? null;
}

/**
 * Drags a field chip with the pointer. The chip's copy follows the pointer by
 * a transform written straight to the element, so a move costs no render;
 * state changes only when the target under the pointer changes.
 */
export function usePivotDrag(onDrop: (field: PivotFieldId, target: PivotDropTarget) => void) {
  const [drag, setDrag] = useState<PivotDrag | null>(null);
  const ghost = useRef<HTMLElement | null>(null);
  const position = useRef({ x: 0, y: 0 });
  const stop = useRef<(() => void) | null>(null);

  useEffect(() => () => stop.current?.(), []);

  const placeGhost = useCallback(() => {
    if (ghost.current) ghost.current.style.transform = `translate(${position.current.x}px, ${position.current.y}px)`;
  }, []);

  /** Give this to the element that follows the pointer. */
  const ghostRef = useCallback(
    (node: HTMLElement | null) => {
      ghost.current = node;
      placeGhost();
    },
    [placeGhost],
  );

  /** Call from `onPointerDown` on a chip's handle. */
  const startDrag = useCallback(
    (field: PivotFieldId, event: ReactPointerEvent<HTMLElement>) => {
      if (event.button !== 0) return;
      event.preventDefault();
      const origin = { x: event.clientX, y: event.clientY };
      let dragging = false;
      let over: PivotDropTarget | null = null;

      const move = (moved: PointerEvent) => {
        if (!dragging && Math.hypot(moved.clientX - origin.x, moved.clientY - origin.y) < DRAG_THRESHOLD) return;
        position.current = { x: moved.clientX, y: moved.clientY };
        placeGhost();
        const next = targetAt(moved.clientX, moved.clientY);
        if (dragging && next === over) return;
        dragging = true;
        over = next;
        setDrag({ field, over });
      };
      const finish = (commit: boolean) => {
        window.removeEventListener("pointermove", move);
        window.removeEventListener("pointerup", release);
        window.removeEventListener("pointercancel", cancel);
        window.removeEventListener("keydown", escape);
        stop.current = null;
        if (!dragging) return;
        setDrag(null);
        if (commit && over) onDrop(field, over);
      };
      const release = () => finish(true);
      const cancel = () => finish(false);
      const escape = (pressed: KeyboardEvent) => {
        if (pressed.key === "Escape") finish(false);
      };

      window.addEventListener("pointermove", move);
      window.addEventListener("pointerup", release);
      window.addEventListener("pointercancel", cancel);
      window.addEventListener("keydown", escape);
      stop.current = cancel;
    },
    [onDrop, placeGhost],
  );

  return { drag, startDrag, ghostRef };
}

"use client";

import { useState } from "react";

import { ChevronDownIcon, ChevronRightIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { Table } from "@/components/ui/table";

import type { PivotColumn, PivotResult } from "../../lib/pivot-compute";
import { pivotMeasure } from "../../lib/pivot-data";

/** Props for the pivot table. */
export interface PivotTableProps {
  result: PivotResult;
  /** Names the row header column, such as "Clinic, then visit type". */
  rowHeading: string;
  /** Tints each innermost cell by its size against the largest one. */
  shade: boolean;
}

// Four tints above none. A cell's number is always printed, so the tint only helps the eye.
const HEAD = "h-10 px-2 text-left align-middle font-medium whitespace-nowrap";
const CELL = "p-2 text-right align-middle whitespace-nowrap tabular-nums";
const SHADES = ["", "bg-chart-1/10", "bg-chart-1/20", "bg-chart-1/30", "bg-chart-1/40"];
const INDENTS = ["pl-2", "pl-6", "pl-10", "pl-14"];

const format = (column: PivotColumn, value: number) => pivotMeasure(column.measure).format(value);

/**
 * The computed pivot as a real table: nested column headings, row groups that
 * fold, a subtotal on every group row, a total column and a grand total row.
 */
export function PivotTable({ result, rowHeading, shade }: PivotTableProps) {
  const [folded, setFolded] = useState<string[]>([]);
  const { columns, headerRows, rows, total, peaks } = result;
  const visible = rows.filter((row) => row.parents.every((key) => !folded.includes(key)));
  const toggle = (key: string) => setFolded((keys) => (keys.includes(key) ? keys.filter((item) => item !== key) : [...keys, key]));

  const shadeOf = (column: PivotColumn, value: number) => {
    const peak = peaks[column.measure];
    if (!shade || column.total || peak === 0) return "";
    return SHADES[Math.min(SHADES.length - 1, Math.floor((value / peak) * SHADES.length))] ?? "";
  };

  return (
      <Table>
        <thead>
          {headerRows.map((cells, level) => (
            <tr key={level} className="border-b border-border">
              {level === 0 ? (
                <th scope="col" rowSpan={headerRows.length} className={cn(HEAD, "sticky left-0 z-10 bg-card align-bottom text-muted-foreground")}>
                  {rowHeading}
                </th>
              ) : null}
              {cells.map((cell) => (
                <th
                  key={cell.key}
                  scope={cell.span > 1 ? "colgroup" : "col"}
                  colSpan={cell.span}
                  className={cn(HEAD, "text-right", level < headerRows.length - 1 ? "border-l border-border" : "font-normal text-muted-foreground")}
                >
                  {cell.label}
                </th>
              ))}
            </tr>
          ))}
        </thead>
        <tbody>
          {visible.map((row) => {
            const open = !folded.includes(row.key);
            return (
              <tr key={row.key} className={cn("border-b border-border hover:bg-muted/50", row.hasChildren ? "bg-muted/30 font-medium" : undefined)}>
                <th scope="row" className={cn(HEAD, "sticky left-0 z-10 bg-card", INDENTS[row.depth] ?? INDENTS[0])}>
                  <span className="flex items-center gap-1">
                    {row.hasChildren ? (
                      <Button
                        variant="ghost"
                        size="icon"
                        aria-expanded={open}
                        aria-label={`${open ? "Fold" : "Unfold"} ${row.label}`}
                        onClick={() => toggle(row.key)}
                      >
                        {open ? <ChevronDownIcon aria-hidden="true" /> : <ChevronRightIcon aria-hidden="true" />}
                      </Button>
                    ) : null}
                    <span className={row.hasChildren ? undefined : "font-normal"}>{row.label}</span>
                    {row.hasChildren ? <span className="font-normal text-muted-foreground">subtotal</span> : null}
                  </span>
                </th>
                {columns.map((column, index) => {
                  const value = row.cells[index] ?? 0;
                  return (
                    <td
                      key={column.key}
                      className={cn(CELL, column.total ? "font-medium" : undefined, row.hasChildren ? undefined : shadeOf(column, value))}
                    >
                      {format(column, value)}
                    </td>
                  );
                })}
              </tr>
            );
          })}
        </tbody>
        <tfoot className="bg-muted font-medium">
          <tr>
            <th scope="row" className={cn(HEAD, "sticky left-0 z-10 bg-muted")}>
              Grand total
            </th>
            {columns.map((column, index) => (
              <td key={column.key} className={cn(CELL, "font-semibold")}>
                {format(column, total[index] ?? 0)}
              </td>
            ))}
          </tr>
        </tfoot>
      </Table>
  );
}

"use client";

import type { ReactNode } from "react";

import { cn } from "@/lib/utils";

import { PIVOT_DROP_ATTRIBUTE, type PivotDropTarget } from "./use-pivot-drag";

/** Props for a well. */
export interface PivotWellProps {
  target: PivotDropTarget;
  label: string;
  /** Read to a screen reader when the well holds no chip. The eye sees "None". */
  empty: string;
  /** Whether a drag is in progress, and whether this well takes the dragged field. */
  dragState: "idle" | "accepts" | "refuses";
  /** The label of the dragged field while it is over this well. A dashed slot shows where it lands. */
  incoming: string | null;
  children: ReactNode[];
}

/**
 * One place fields can sit: a labelled box of chips that is also a drop
 * target. During a drag it says in words whether it takes the field.
 */
export function PivotWell({ target, label, empty, dragState, incoming, children }: PivotWellProps) {
  const dropAttribute = { [PIVOT_DROP_ATTRIBUTE]: target };
  return (
    <div
      {...dropAttribute}
      role="group"
      aria-label={label}
      className={cn(
        "flex min-h-24 flex-col gap-2 rounded-xl border bg-muted/40 p-3 motion-safe:transition-colors motion-safe:duration-150",
        dragState === "accepts" ? "border-dashed border-foreground/40" : "border-border",
        incoming ? "bg-muted" : undefined,
        dragState === "refuses" ? "opacity-50" : undefined,
      )}
    >
      <h3 className="text-sm font-medium">{label}</h3>
      <div className="flex flex-wrap items-center gap-2">
        {children}
        {incoming ? (
          <span className="inline-flex min-h-11 items-center rounded-lg border border-dashed border-foreground/50 px-3 text-sm whitespace-nowrap text-muted-foreground sm:min-h-9">
            {incoming}
            <span className="sr-only"> lands here</span>
          </span>
        ) : null}
        {children.length === 0 && !incoming ? (
          <p className="flex min-h-11 items-center text-sm whitespace-nowrap text-muted-foreground sm:min-h-9">
            {dragState === "refuses" ? "Not here" : "None"}
            <span className="sr-only">. {dragState === "refuses" ? "This field does not go here." : empty}</span>
          </p>
        ) : null}
      </div>
    </div>
  );
}
